import SwiftUIstruct TasksView2: View {        @State var tasks: [TaskItem]    let primaryBackground = Color(red: 28/255, green: 28/255, blue: 30/255)    let cardBackgroundColor = Color(red: 44/255, green: 44/255, blue: 46/255)    let accentColor = Color(red: 255/255, green: 87/255, blue: 51/255)    var body: some View {        ZStack {            primaryBackground.ignoresSafeArea()            ScrollView {                VStack(spacing: 20) {                    // ➤ Título                    Text("Tareas")                        .font(.largeTitle.bold())                        .foregroundColor(.white)                        .frame(maxWidth: .infinity, alignment: .leading)                        .padding(.horizontal)                        .padding(.top)                    // ➤ Agrupado por materia                    let grouped = Dictionary(grouping: tasks, by: { $0.subjectName })                    ForEach(grouped.keys.sorted(), id: \.self) { subject in                        VStack(alignment: .leading, spacing: 16) {                            Text(subject)                                .font(.title2.bold())                                .foregroundColor(.white)                                .padding(.horizontal)                            VStack(spacing: 28) {                                ForEach(grouped[subject]!) { task in                                    TimelineTaskRow(                                        task: task,                                        toggle: { toggleTask(task) }                                    )                                }                            }                            .padding(.leading, 28)                        }                    }                }                .padding(.bottom)            }        }        .preferredColorScheme(.dark)    }    func toggleTask(_ task: TaskItem) {        if let index = tasks.firstIndex(where: { $0.id == task.id }) {            withAnimation(.spring()) {                tasks[index].isCompleted.toggle()            }        }    }}struct TimelineTaskRow: View {    let task: TaskItem    let toggle: () -> Void    let cardBackground = Color(red: 44/255, green: 44/255, blue: 46/255)    let accent = Color(red: 255/255, green: 87/255, blue: 51/255)    var body: some View {        HStack(alignment: .top, spacing: 16) {            // ➤ Línea del timeline            VStack {                Circle()                    .fill(task.isCompleted ? .green : accent)                    .frame(width: 14, height: 14)                Rectangle()                    .fill(Color.gray.opacity(0.5))                    .frame(width: 3)                    .frame(maxHeight: .infinity)            }            // ➤ Tarjeta            VStack(alignment: .leading, spacing: 6) {                HStack {                    Text(task.title)                        .font(.headline)                        .foregroundColor(.white)                    Spacer()                    Button(action: toggle) {                        Image(systemName: task.isCompleted ? "checkmark.circle.fill" : "circle")                            .foregroundColor(task.isCompleted ? .green : accent)                            .font(.title3)                    }                }                // Descripción                if !task.description.isEmpty {                    Text(task.description)                        .font(.subheadline)                        .foregroundColor(.white.opacity(0.8))                        .padding(.top, 2)                }                // Fecha                Text("Entrega: \(task.dueDate.formatted(date: .abbreviated, time: .omitted))")                    .font(.caption)                    .foregroundColor(.white.opacity(0.6))                    .padding(.top, 4)            }            .padding()            .background(cardBackground)            .cornerRadius(16)            .shadow(color: accent.opacity(0.15), radius: 6, x: 0, y: 3)            .animation(.spring(), value: task.isCompleted)        }    }}#Preview {    TasksView2(tasks: [        TaskItem(            subjectName: "Cálculo Integral",            title: "Tarea 1: Integrales",            description: "Resolver ejercicios del 1 al 10.",            dueDate: Date().addingTimeInterval(86400),            isCompleted: false        ),        TaskItem(            subjectName: "Cálculo Integral",            title: "Proyecto Final",            description: "Desarrollar un programa que resuelva integrales numéricas.",            dueDate: Date().addingTimeInterval(172800),            isCompleted: true        ),        TaskItem(            subjectName: "Programación",            title: "UI en Swift",            description: "Crear una interfaz usando VStack, HStack y ZStack.",            dueDate: Date().addingTimeInterval(259200),            isCompleted: false        )    ])}